"""Fixed SQL only; never execute SQL generated by the model."""
from datetime import timedelta
from pathlib import Path

from psycopg.types.json import Jsonb

from competitor_db import connect


MAX_HISTORY_GROUPS = 5000


def load_snapshot(settings, now):
    start = now.date()
    end = start + timedelta(days=settings.horizon_days)
    cutoff = now - timedelta(days=settings.freshness_days)
    history_cutoff = now - timedelta(days=settings.history_days)
    with connect() as conn:
        conn.execute("SET TRANSACTION READ ONLY")
        conn.execute("SET LOCAL statement_timeout = '30s'")
        # Scope BEFORE deduplication: the global latest view can mix own hotels.
        rows = conn.execute("""
            WITH latest AS (
                SELECT DISTINCT ON (p.hotel_key, p.stay_date, p.adults,
                                    p.children_ages, p.rooms_requested)
                       p.hotel_key, p.stay_date, p.adults, p.children_ages,
                       p.rooms_requested, p.nightly_jpy, p.collected_at
                FROM daily_hotel_prices p
                JOIN collection_batches b ON b.id=p.batch_id
                JOIN collection_queries q ON q.id=p.query_id
                WHERE b.own_hotel=%s AND b.status='succeeded' AND q.status='stored'
                  AND p.stay_date >= %s AND p.stay_date < %s
                  AND p.collected_at >= %s AND p.collected_at <= %s
                  AND p.nightly_jpy > 0 AND p.currency='JPY'
                ORDER BY p.hotel_key, p.stay_date, p.adults, p.children_ages,
                         p.rooms_requested, p.collected_at DESC, p.id DESC
            )
            SELECT stay_date, adults, children_ages, rooms_requested,
                   count(*), min(nightly_jpy),
                   percentile_cont(0.5) WITHIN GROUP (ORDER BY nightly_jpy),
                   max(nightly_jpy), min(collected_at), max(collected_at)
            FROM latest
            GROUP BY stay_date, adults, children_ages, rooms_requested
            ORDER BY stay_date, adults, children_ages, rooms_requested
            LIMIT 501
        """, (settings.hotel, start, end, cutoff, now)).fetchall()
        history_rows = conn.execute("""
            WITH observations AS (
                -- Deduplicate a collection instant, never the entire time series.
                SELECT DISTINCT ON (
                    p.hotel_key, p.check_in, p.check_out,
                    p.adults, p.children_ages, p.rooms_requested, p.collected_at
                ) p.hotel_key, p.check_in, p.check_out,
                  p.adults, p.children_ages, p.rooms_requested,
                  p.nightly_jpy, p.collected_at
                FROM hotel_quotes p
                JOIN collection_queries q ON q.id=p.query_id
                JOIN collection_batches b ON b.id=q.batch_id
                WHERE b.own_hotel=%s AND b.status='succeeded' AND q.status='stored'
                  AND p.status='match'
                  AND p.check_in >= %s AND p.check_in < %s
                  AND p.collected_at >= %s AND p.collected_at <= %s
                  AND p.nightly_jpy > 0 AND p.currency='JPY'
                ORDER BY p.hotel_key, p.check_in, p.check_out,
                         p.adults, p.children_ages, p.rooms_requested,
                         p.collected_at, p.id DESC
            )
            SELECT hotel_key, check_in, check_out,
                   adults, children_ages, rooms_requested,
                   jsonb_agg(jsonb_build_object(
                       'collected_at', collected_at, 'nightly_jpy', nightly_jpy
                   ) ORDER BY collected_at) AS observations
            FROM observations
            GROUP BY hotel_key, check_in, check_out,
                     adults, children_ages, rooms_requested
            ORDER BY check_in, check_out, hotel_key,
                     adults, children_ages, rooms_requested
            LIMIT %s
        """, (settings.hotel, start, end, history_cutoff, now,
              MAX_HISTORY_GROUPS + 1)).fetchall()
        self_price_comparisons = _load_self_price_comparisons(
            conn, settings.hotel, start, end, cutoff, now)
    if len(rows) > 500:
        raise ValueError("报价分组超过500，请缩短 MARKETING_HORIZON_DAYS")
    groups = [dict(evidence_id=f"price-{i:03d}", stay_date=str(r[0]), adults=r[1],
                   children_ages=r[2], rooms=r[3], hotel_count=r[4],
                   min_jpy=float(r[5]), median_jpy=float(r[6]), max_jpy=float(r[7]),
                   oldest_observation=r[8].isoformat(), newest_observation=r[9].isoformat())
              for i, r in enumerate(rows, 1)]
    if len(history_rows) > MAX_HISTORY_GROUPS:
        raise ValueError(f"历史价格分组超过{MAX_HISTORY_GROUPS}，请缩短 MARKETING_HORIZON_DAYS")
    price_history = [dict(
        evidence_id=f"history-{i:03d}", hotel_key=r[0],
        check_in=str(r[1]), check_out=str(r[2]),
        adults=r[3], children_ages=r[4], rooms=r[5],
        observations=r[6],
    ) for i, r in enumerate(history_rows, 1)]
    return dict(own_hotel=settings.hotel, as_of=now.isoformat(), currency="JPY",
                window_start=str(start), window_end_exclusive=str(end), groups=groups,
                price_history=price_history,
                self_price_comparisons=self_price_comparisons,
                history_start=history_cutoff.isoformat(),
                limitations=["仅含成功采集的JPY报价；groups为近期单晚市场价，price_history为固定入住/退房日期的每晚报价历史；缺报价不等于售罄。",
                             "报价不代表成交价，税费与房型可比性、实际入住容量仍需核对。",
                             "未接入本店订单、库存、成本、营销预算和活动效果，不能计算入住率、利润或营销ROI。",
                             "历史序列按酒店、入住/退房日期、成人数、儿童年龄及房间数分组；不能把跨组价差解释为时间趋势。",
                             "历史报价未锁定相同房型或套餐；仅一次观测不能判断趋势，预测属于待验证推断。",
                             "本店价格比对使用新鲜度窗口内双方各自最新报价，并非同步采集；日期和人数匹配不代表房型、套餐及税费完全可比。价差为本店减竞品，不能据此直接推算利润。"])


def _load_self_price_comparisons(conn, hotel, start, end, cutoff, now):
    """Compare fresh quotes for identical stays; preserve each own room/rate/source."""
    rows = conn.execute("""
        WITH own_latest AS (
            SELECT DISTINCT ON (
                check_in, check_out, adults, children_ages, rooms_requested,
                room_type, rate_plan, source
            ) check_in, check_out, nights, adults, children_ages,
              total_guests, rooms_requested, nightly_jpy, stay_total_jpy,
              room_type, rate_plan, tax_inclusion, source, collected_at
            FROM self_quotes
            WHERE hotel_name=%s
              AND check_in >= %s AND check_in < %s
              AND collected_at >= %s AND collected_at <= %s
              AND nightly_jpy > 0 AND currency='JPY'
            ORDER BY check_in, check_out, adults, children_ages, rooms_requested,
                     room_type, rate_plan, source, collected_at DESC, id DESC
        ), competitor_latest AS (
            SELECT DISTINCT ON (
                p.hotel_key, p.check_in, p.check_out,
                p.adults, p.children_ages, p.rooms_requested
            ) p.hotel_key, p.name, p.check_in, p.check_out, p.nights, p.adults,
              p.children_ages, p.total_guests, p.rooms_requested,
              p.nightly_jpy, p.stay_total_jpy, p.tax_inclusion, p.collected_at
            FROM hotel_quotes p
            JOIN collection_queries q ON q.id=p.query_id
            JOIN collection_batches b ON b.id=q.batch_id
            WHERE b.own_hotel=%s AND b.status='succeeded' AND q.status='stored'
              AND p.status='match' AND p.name IS DISTINCT FROM %s
              AND p.check_in >= %s AND p.check_in < %s
              AND p.collected_at >= %s AND p.collected_at <= %s
              AND p.nightly_jpy > 0 AND p.currency='JPY'
            ORDER BY p.hotel_key, p.check_in, p.check_out,
                     p.adults, p.children_ages, p.rooms_requested,
                     p.collected_at DESC, p.id DESC
        )
        SELECT jsonb_build_object(
            'own_quote', jsonb_build_object(
                'check_in', s.check_in, 'check_out', s.check_out,
                'adults', s.adults, 'children_ages', s.children_ages,
                'rooms', s.rooms_requested,
                'nightly_jpy', s.nightly_jpy, 'stay_total_jpy', s.stay_total_jpy,
                'room_type', s.room_type, 'rate_plan', s.rate_plan,
                'tax_inclusion', s.tax_inclusion, 'source', s.source,
                'collected_at', s.collected_at
            ),
            'competitor_count', m.hotel_count,
            'market_min_jpy', m.min_jpy,
            'market_median_jpy', m.median_jpy,
            'market_max_jpy', m.max_jpy,
            'difference_from_median_percent',
                round(((s.nightly_jpy / nullif(m.median_jpy, 0) - 1) * 100)::numeric, 2),
            'competitors', coalesce(m.competitors, '[]'::jsonb)
        )
        FROM own_latest s
        CROSS JOIN LATERAL (
            SELECT count(*) AS hotel_count,
                   min(c.nightly_jpy) AS min_jpy,
                   percentile_cont(0.5) WITHIN GROUP (ORDER BY c.nightly_jpy) AS median_jpy,
                   max(c.nightly_jpy) AS max_jpy,
                   jsonb_agg(jsonb_build_object(
                       'hotel_key', c.hotel_key, 'name', c.name,
                       'nightly_jpy', c.nightly_jpy,
                       'stay_total_jpy', c.stay_total_jpy,
                       'tax_inclusion', c.tax_inclusion,
                       'collected_at', c.collected_at
                   ) ORDER BY c.hotel_key) AS competitors
            FROM competitor_latest c
            WHERE c.check_in=s.check_in AND c.check_out=s.check_out
              AND c.nights=s.nights AND c.adults=s.adults
              AND c.children_ages=s.children_ages AND c.total_guests=s.total_guests
              AND c.rooms_requested=s.rooms_requested
        ) m
        ORDER BY s.check_in, s.check_out, s.adults, s.children_ages,
                 s.rooms_requested, s.room_type, s.rate_plan, s.source
        LIMIT %s
    """, (hotel, start, end, cutoff, now,
          hotel, hotel, start, end, cutoff, now, MAX_HISTORY_GROUPS + 1)).fetchall()
    if len(rows) > MAX_HISTORY_GROUPS:
        raise ValueError(f"本店价格比对分组超过{MAX_HISTORY_GROUPS}，请缩短 MARKETING_HORIZON_DAYS")
    return [dict(r[0], evidence_id=f"comparison-{i:03d}")
            for i, r in enumerate(rows, 1)]


class ReportStore:
    def __init__(self, hotel):
        self.hotel = hotel

    @staticmethod
    def initialize():
        with connect() as conn:
            conn.execute((Path(__file__).resolve().parents[1] / "sql/004_a_marketing_reports.sql").read_text(encoding="utf-8"))
            conn.execute((Path(__file__).resolve().parents[1] / "sql/005_a_report_emails.sql").read_text(encoding="utf-8"))

    def get(self, key):
        with connect() as conn:
            row = conn.execute("SELECT run_key,status,payload FROM a_marketing_reports WHERE own_hotel=%s AND run_key=%s",
                               (self.hotel, key)).fetchone()
        return dict(run_key=row[0], status=row[1], payload=row[2]) if row else None

    def claim_email(self, key, recipient, retry=False):
        with connect() as conn:
            row = conn.execute("""INSERT INTO a_report_emails(own_hotel,run_key,recipient,status)
                VALUES (%s,%s,%s,'sending') ON CONFLICT (own_hotel,run_key) DO UPDATE
                SET status='sending',recipient=EXCLUDED.recipient,error_type=NULL,updated_at=now()
                WHERE a_report_emails.status='failed' AND %s RETURNING run_key""",
                (self.hotel, key, recipient, retry)).fetchone()
        return row is not None

    def finish_email(self, key, status, error_type=None):
        with connect() as conn:
            conn.execute("""UPDATE a_report_emails SET status=%s,error_type=%s,updated_at=now()
                WHERE own_hotel=%s AND run_key=%s""", (status, error_type, self.hotel, key))

    def claim(self, key):
        with connect() as conn:
            row = conn.execute("""INSERT INTO a_marketing_reports(own_hotel,run_key,status,payload)
                VALUES (%s, %s, 'running', '{}'::jsonb)
                ON CONFLICT (own_hotel,run_key) DO NOTHING RETURNING id""", (self.hotel, key)).fetchone()
            return row is not None

    def save(self, key, status, payload):
        with connect() as conn:
            cursor = conn.execute("""UPDATE a_marketing_reports
                SET status=%s,payload=%s,updated_at=CURRENT_TIMESTAMP
                WHERE own_hotel=%s AND run_key=%s""", (status, Jsonb(payload), self.hotel, key))
            if cursor.rowcount != 1:
                raise LookupError("营销运行记录不存在")

    def latest(self):
        with connect() as conn:
            row = conn.execute("""SELECT run_key,status,payload FROM a_marketing_reports
                WHERE own_hotel=%s ORDER BY id DESC LIMIT 1""", (self.hotel,)).fetchone()
        return dict(run_key=row[0], status=row[1], payload=row[2]) if row else None
